class Solution:
    def maxDepthBST(self, order: List[int]) -> int:
        lc, rc = {}, {}
        root = order[0]
        ans = 1
        for v in order[1:]:
            cur, d = root, 1
            while True:
                d += 1
                nxt = lc if v < cur else rc
                child = nxt.get(cur)
                if child is None:
                    nxt[cur] = v
                    break
                cur = child
            ans = max(ans, d)
        return ans

