class Solution {
public:
    int maxDepthBST(vector<int>& order) {
        unordered_map<int, int> lc, rc;
        int root = order[0], ans = 1;
        for (size_t i = 1; i < order.size(); ++i) {
            int v = order[i], cur = root, d = 1;
            while (true) {
                ++d;
                auto& ch = (v < cur) ? lc : rc;
                auto it = ch.find(cur);
                if (it == ch.end()) { ch[cur] = v; break; }
                cur = it->second;
            }
            ans = max(ans, d);
        }
        return ans;
    }
};

