class Solution {
    public int maxDepthBST(int[] order) {
        Map<Integer, Integer> lc = new HashMap<>(), rc = new HashMap<>();
        int root = order[0], ans = 1;
        for (int i = 1; i < order.length; i++) {
            int v = order[i], cur = root, d = 1;
            while (true) {
                d++;
                Map<Integer, Integer> ch = v < cur ? lc : rc;
                Integer nxt = ch.get(cur);
                if (nxt == null) { ch.put(cur, v); break; }
                cur = nxt;
            }
            ans = Math.max(ans, d);
        }
        return ans;
    }
}

