from sortedcontainers import SortedList

class Solution:
    def maxDepthBST(self, order: List[int]) -> int:
        sl = SortedList()
        depth = {}
        ans = 0
        for v in order:
            i = sl.bisect_left(v)
            d = 1
            if i > 0:
                d = max(d, depth[sl[i - 1]] + 1)
            if i < len(sl):
                d = max(d, depth[sl[i]] + 1)
            depth[v] = d
            sl.add(v)
            ans = max(ans, d)
        return ans

