class Solution {
public:
    int maxDepthBST(vector<int>& order) {
        map<int, int> depth;
        int ans = 0;
        for (int v : order) {
            auto it = depth.lower_bound(v);
            int d = 1;
            if (it != depth.end()) d = max(d, it->second + 1);
            if (it != depth.begin()) d = max(d, prev(it)->second + 1);
            depth[v] = d;
            ans = max(ans, d);
        }
        return ans;
    }
};

