class Solution {
    public int maxDepthBST(int[] order) {
        TreeMap<Integer, Integer> depth = new TreeMap<>();
        int ans = 0;
        for (int v : order) {
            int d = 1;
            Integer succ = depth.ceilingKey(v);
            if (succ != null) d = Math.max(d, depth.get(succ) + 1);
            Integer pred = depth.floorKey(v);
            if (pred != null) d = Math.max(d, depth.get(pred) + 1);
            depth.put(v, d);
            ans = Math.max(ans, d);
        }
        return ans;
    }
}

