var maxDepthBST = function(order) {
    const keys = [];
    const depth = new Map();
    let ans = 0;
    for (const v of order) {
        let lo = 0, hi = keys.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (keys[mid] < v) lo = mid + 1;
            else hi = mid;
        }
        let d = 1;
        if (lo > 0) d = Math.max(d, depth.get(keys[lo - 1]) + 1);
        if (lo < keys.length) d = Math.max(d, depth.get(keys[lo]) + 1);
        depth.set(v, d);
        keys.splice(lo, 0, v);
        ans = Math.max(ans, d);
    }
    return ans;
};
